import{_ as t,o,c as a,a5 as n}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"keep-alive 的使用场景和原理","description":"使用场景 \\\\<keep alive\\\\ 是 Vue.js 提供的一个内置组件，用于缓存动态组件，避免重复渲染，提高性能。常见的使用场景包括： 1. 组件切换 ：在同一个视图中切换不同的子组件时，使用 \\\\<keep alive\\\\ 可以避免组件被销毁和重建，从而保留组件的状态和缓存。","frontmatter":{"title":"keep-alive 的使用场景和原理","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"使用场景 \\\\<keep alive\\\\ 是 Vue.js 提供的一个内置组件，用于缓存动态组件，避免重复渲染，提高性能。常见的使用场景包括： 1. 组件切换 ：在同一个视图中切换不同的子组件时，使用 \\\\<keep alive\\\\ 可以避免组件被销毁和重建，从而保留组件的状态和缓存。","sidebarWeight":19,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/`keep-alive` 的使用场景和原理.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/keep-alive 的使用场景和原理.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/keep-alive 的使用场景和原理.md"}'),l={name:"posts/Vue系统教程/02-模板、组件与交互/keep-alive 的使用场景和原理.md"};function i(r,e,p,s,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<div><h1 id="keep-alive-的使用场景和原理" tabindex="-1">keep-alive 的使用场景和原理 <a class="header-anchor" href="#keep-alive-的使用场景和原理" aria-label="Permalink to &quot;keep-alive 的使用场景和原理&quot;">​</a></h1><blockquote><p>本节目标：理解“keep-alive 的使用场景和原理”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h4 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h4><p><code>\\&lt;keep-alive\\&gt;</code> 是 Vue.js 提供的一个内置组件，用于缓存动态组件，避免重复渲染，提高性能。常见的使用场景包括：</p><ol><li><strong>组件切换</strong>：在同一个视图中切换不同的子组件时，使用 <code>\\&lt;keep-alive\\&gt;</code> 可以避免组件被销毁和重建，从而保留组件的状态和缓存。</li><li><strong>路由组件缓存</strong>：在使用 Vue Router 时，对需要缓存的路由组件使用 <code>\\&lt;keep-alive\\&gt;</code>，可以在用户切换路由时保留组件状态和数据。</li><li><strong>提升性能</strong>：对于一些性能开销较大的组件，使用 <code>\\&lt;keep-alive\\&gt;</code> 可以减少组件销毁和重建的频率，提升性能。</li></ol><h4 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h4><h5 id="基本使用" tabindex="-1">基本使用 <a class="header-anchor" href="#基本使用" aria-label="Permalink to &quot;基本使用&quot;">​</a></h5><p>&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;button @click=&quot;currentComponent = &#39;ComponentA&#39;&quot;&gt;Show Component A&lt;/button&gt; &lt;button @click=&quot;currentComponent = &#39;ComponentB&#39;&quot;&gt;Show Component B&lt;/button&gt; &lt;keep-alive&gt; &lt;component :is=&quot;currentComponent&quot;&gt;&lt;/component&gt; &lt;/keep-alive&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; import ComponentA from &#39;./ComponentA.vue&#39;; import ComponentB from &#39;./ComponentB.vue&#39;; export default { data() { return { currentComponent: &#39;ComponentA&#39; }; }, components: { ComponentA, ComponentB } }; &lt;/script&gt;</p><h5 id="路由组件缓存" tabindex="-1">路由组件缓存 <a class="header-anchor" href="#路由组件缓存" aria-label="Permalink to &quot;路由组件缓存&quot;">​</a></h5><p>&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;router-view&gt;&lt;/router-view&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { name: &#39;App&#39; }; &lt;/script&gt;</p><p>// router/index.js import Vue from &#39;vue&#39;; import Router from &#39;vue-router&#39;; import Home from &#39;@/components/Home.vue&#39;; import About from &#39;@/components/About.vue&#39;; Vue.use(Router); export default new Router({ routes: [ { path: &#39;/&#39;, name: &#39;Home&#39;, component: Home }, { path: &#39;/about&#39;, name: &#39;About&#39;, component: About, meta: { keepAlive: true } } ] });</p><p>&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;keep-alive&gt; &lt;router-view v-if=&quot;$route.meta.keepAlive&quot;&gt;&lt;/router-view&gt; &lt;/keep-alive&gt; &lt;router-view v-if=&quot;!$route.meta.keepAlive&quot;&gt;&lt;/router-view&gt; &lt;/div&gt; &lt;/template&gt;</p><h4 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h4><p><code>\\&lt;keep-alive\\&gt;</code> 的实现原理是通过缓存不活动的组件实例，当组件重新激活时，恢复之前的状态，而不是重新创建组件实例。以下是其主要原理：</p><ol><li><strong>缓存机制</strong>：<code>\\&lt;keep-alive\\&gt;</code> 会将不活动的组件实例缓存到内存中，而不是销毁它们。</li><li><strong>生命周期钩子</strong>：使用 <code>\\&lt;keep-alive\\&gt;</code> 的组件会新增两个生命周期钩子：</li></ol><ul><li><code>activated</code>：当组件被激活时调用。</li><li><code>deactivated</code>：当组件被停用时调用。</li></ul><ol start="3"><li><strong>VNode 的缓存</strong>：<code>\\&lt;keep-alive\\&gt;</code> 通过维护一个缓存对象，将不活动的组件对应的 VNode 缓存起来。当组件需要重新激活时，从缓存中取出对应的 VNode。</li></ol><h4 id="代码实现-简化版" tabindex="-1">代码实现（简化版） <a class="header-anchor" href="#代码实现-简化版" aria-label="Permalink to &quot;代码实现（简化版）&quot;">​</a></h4><p>以下是 <code>\\&lt;keep-alive\\&gt;</code> 的简化实现示例： const KeepAlive = { name: &#39;keep-alive&#39;, abstract: true, props: { include: RegExp, exclude: RegExp }, created() { this.cache = Object.create(null); this.keys = []; }, destroyed() { for (const key in this.cache) { pruneCacheEntry(this.cache, key, this.keys); } }, render() { const vnode = this.$slots.default ? this.$slots.default[0] : null; if (vnode &amp;&amp; vnode.componentOptions) { const key = vnode.key == null ? vnode.componentOptions.Ctor.cid + (vnode.componentOptions.tag ? <code>::${vnode.componentOptions.tag}</code> : &#39;&#39;) : vnode.key; if (this.cache[key]) { vnode.componentInstance = this.cache[key].componentInstance; this.keys.splice(this.keys.indexOf(key), 1); this.keys.push(key); } else { this.cache[key] = vnode; this.keys.push(key); if (this.max &amp;&amp; this.keys.length &gt; parseInt(this.max)) { pruneCacheEntry(this.cache, this.keys[0], this.keys, this._vnode); } } vnode.data.keepAlive = true; } return vnode || (this.$slots.default &amp;&amp; this.$slots.default[0]); } }; function pruneCacheEntry(cache, key, keys, current) { const entry = cache[key]; if (entry &amp;&amp; (!current || entry.tag !== current.tag)) { entry.componentInstance.$destroy(); } cache[key] = null; keys.splice(keys.indexOf(key), 1); }</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p><code>\\&lt;keep-alive\\&gt;</code> 组件用于缓存动态组件，避免重复渲染，提高性能。它通过缓存组件实例和 VNode，在组件重新激活时恢复之前的状态，提供了高效的组件管理方式。常用于组件切换和路由组件缓存等场景。</p></div>',1)])])}const m=t(l,[["render",i]]);export{h as __pageData,m as default};
